    if (hasLabel(pr, 'pr_approved')) return 'approved_queue';
    if (hasLabel(pr, 'ai_pr_reviewed')) return 'review';
    if (pr && pr.checks && ACTIVE_RUN_STATES.indexOf(pr.checks.verdict) !== -1) {
        return 'pr_validation';
    }
    return 'pr_created';
