                    repoInfo: spRepo,
                    prs: spPrList,
                    mergedPrs: spMerged,
                    issues: spIssues,
                    machineAuthor: machineAuthorModule.resolveMachineAuthor(
                        RUN_JOB_PARAMS, effectiveConfig),
                    tokens: spTokens,
                    runs: spRunList,
                    checkNames: validationCheckNames() || [],
                    prev: spPrev,
                    dryRun: DRY,
