            var spCfg = spCfgRaw;
            var spRepo = (spCfg.repo ? (function () {
                    var parts = String(spCfg.repo).split('/');
                    return { owner: parts[0], repo: parts[1] };
                })() : (effectiveRepoInfo && effectiveRepoInfo.owner) ?
                effectiveRepoInfo : null);
