                    var spD = mcpParse(github_search_issues({
                        query: 'repo:' + spFull + ' is:issue is:open'
                    }));
                    spIssues = Array.isArray(spD) ? spD :
                        ((spD && (spD.items || spD.data)) || []);
                } catch (eDevs) { /* development + backlog empty this tick */ }
