    validationCheckSync = { repo: repoKey, at: now };
    var ciWorkflow = ((RUN_JOB_PARAMS || {}).ciWorkflow) || 'quality.yml';
    var prs = mcpParse(github_list_prs({
        workspace: repoInfo.owner, repository: repoInfo.repo, state: 'open'
