function failedRunLinksLine(repoInfo, ciWorkflow, headSha) {
    if (!repoInfo || !ciWorkflow || !headSha) return '';
    try {
        var runs = mcpParse(github_list_workflow_runs({
            workspace: repoInfo.owner, repository: repoInfo.repo,
