                var spPrev = factoryStateModule.fetchPreviousState(
                    spFull, spCfg, function (a) {
                        return cli_execute_command(a);
                    });
                var spState = factoryStateModule.buildFactoryState({
                    repoInfo: spRepo,
                    prs: spPrList,
                    mergedPrs: spMerged,
