4. `headVerdict(sha)` rewrite:
```js
function freshest(runs) {
    return (runs || []).slice().sort(function (a, b) {
        return String(b.updated_at || b.created_at || '').localeCompare(
               String(a.updated_at || a.created_at || ''));
    })[0] || null;
}
function headVerdict(sha) {
    var mine = headRuns(sha);
    var real = mine.filter(function (r) { return isValidationRun(r, ciWorkflow); });
    var side = mine.filter(function (r) { return !isValidationRun(r, ciWorkflow); });
    var terminal = real.filter(function (r) {
