    var cite = terminal.length ? freshest(terminal) : freshest(real.filter(isActive));
    var aux = freshest(side);   // auxiliary evidence only — never the cite
    ...
    return cite ? { ...record(cite), auxiliary: aux ? record(aux) : undefined } : null;
}
```

