        console.log('  ℹ️  validation-sync: 0 runs from ' + ciWorkflow +
                    ' — raw: ' + JSON.stringify(runs).slice(0, 200));
    }
    var syncDebug = { armed: armed.length, runs: runList.length };
    armed.forEach(function (pr) {
