var MERGED_WINDOW_MS = 24 * 60 * 60 * 1000;   // merged_recent retention
var DEV_LABEL = 'agent:dev';                  // dev-leg handoff (machine label)
var DEV_DONE_LABEL = 'ai_developed';          // dev leg produced a green PR

