    var prList = Array.isArray(prs) ? prs :
        ((prs && (prs.pullRequests || prs.data || prs.items)) || []);
    var armed = prList.filter(function (pr) {
        return pr.head && pr.head.sha && pr.head.ref &&
            (pr.labels || []).some(function (l) {
                return (l && l.name) === 'ai_validating';
