    // The audit-trail record for one run: verdict + the identity fields the
    // merged_recent persistence needs (run id + name + sha + conclusion).
    function runCite(r) {
        var t = runClock(r);
        var done = r.status === 'completed';
        return {
            verdict: done ? (r.conclusion || r.status) : r.status,
            at: r.created_at,
            url: r.html_url,
            runId: r.id == null ? null : r.id,
            name: r.name || null,
            sha: r.head_sha || null,
            conclusion: done ? (r.conclusion || null) : null,
            runStartedAt: t.runStartedAt,
            updatedAt: t.updatedAt
        };
    }
    // Cite resolution (gh-816): newest TERMINAL non-cancelled real run
    // decides (cancelled is never a verdict — gh-191), else the newest
    // active real run, else NO cite — a head with only SM side-run legs
    // has no validation evidence to discharge. The freshest side-run leg
    // (when any) rides along as auxiliary evidence, never as the cite.
    function headVerdict(sha) {
        var mine = headRuns(sha);
        var real = mine.filter(isRealRun);
        var legs = mine.filter(function (r) { return !isRealRun(r); });
