            return r && r.event === 'workflow_dispatch' &&
                r.head_sha === headSha &&
                r.status === 'completed' &&
                (r.conclusion === 'failure' || r.conclusion === 'timed_out');
        });
        red.sort(function (a, b) {
            return new Date(b.updated_at || b.created_at).getTime() -
                   new Date(a.updated_at || a.created_at).getTime();
