    // evidence at most, never the discharge cite. A dispatch without a path
    // (payload shape drift) fails OPEN as real — a run that cannot be
    // classified must not silently lose citability.
    function headRuns(sha) {
        return runs.filter(function (r) {
            return r && r.head_sha === sha;
        });
    }
    function isRealRun(r) {
        if (!r) return false;
        if (r.event !== 'workflow_dispatch') return true;
        return !r.path || isValidationWorkflowPath(r.path, ciWorkflow);
    }
    function runClock(r) {
        return {
            runStartedAt: (r && r.run_started_at) || null,
            updatedAt: (r && r.updated_at) || null
