    // gh-816 citation integrity: the lane cite is the discharge evidence,
    // so only REAL validation runs may carry it. A real validation run is
    // (a) repo CI arriving on a non-dispatch event (push/pull_request/
    // schedule — full CI + dynamic PR-validation workflows), or (b) the
    // machine's own validation-workflow dispatch (path
    // .github/workflows/<ciWorkflow>). Any OTHER dispatch on the head is an
    // SM side-run leg (review/develop/rework on ai-teammate.yml) — auxiliary
    // evidence at most, never the discharge cite. A dispatch without a path
    // (payload shape drift) fails OPEN as real — a run that cannot be
    // classified must not silently lose citability.
    function headRuns(sha) {
        return runs.filter(function (r) {
            return r && r.head_sha === sha;
        });
    }
    function isRealRun(r) {
        if (!r) return false;
        if (r.event !== 'workflow_dispatch') return true;
        return !r.path || isValidationWorkflowPath(r.path, ciWorkflow);
    }
    function runClock(r) {
        return {
            runStartedAt: (r && r.run_started_at) || null,
            updatedAt: (r && r.updated_at) || null
        };
    }
    // Freshest by the run's own clock (REST lists are newest-first but the
    // list is shared with leg runs — sort explicitly, like
    // syncValidationChecks/failedRunLinksLine do).
    function freshestRun(list) {
        return (list || []).slice().sort(function (a, b) {
            return String((b && (b.updated_at || b.created_at)) || '')
                .localeCompare(String((a && (a.updated_at || a.created_at)) || ''));
        })[0] || null;
    }
    // The audit-trail record for one run: verdict + the identity fields the
    // merged_recent persistence needs (run id + name + sha + conclusion).
    function runCite(r) {
        var t = runClock(r);
        var done = r.status === 'completed';
        return {
            verdict: done ? (r.conclusion || r.status) : r.status,
            at: r.created_at,
            url: r.html_url,
            runId: r.id == null ? null : r.id,
            name: r.name || null,
            sha: r.head_sha || null,
            conclusion: done ? (r.conclusion || null) : null,
            runStartedAt: t.runStartedAt,
            updatedAt: t.updatedAt
        };
    }
    // Cite resolution (gh-816): newest TERMINAL non-cancelled real run
    // decides (cancelled is never a verdict — gh-191), else the newest
    // active real run, else NO cite — a head with only SM side-run legs
    // has no validation evidence to discharge. The freshest side-run leg
    // (when any) rides along as auxiliary evidence, never as the cite.
    function headVerdict(sha) {
        var mine = headRuns(sha);
        var real = mine.filter(isRealRun);
        var legs = mine.filter(function (r) { return !isRealRun(r); });
        var cite = freshestRun(real.filter(function (r) {
            return r.status === 'completed' && r.conclusion &&
                   r.conclusion !== 'cancelled';
        })) || freshestRun(real.filter(function (r) {
            return ACTIVE_RUN_STATES.indexOf(r.status) !== -1;
        }));
        if (!cite) return null;
        var out = runCite(cite);
        var leg = freshestRun(legs);
        if (leg) {
            out.auxiliary = {
                runId: leg.id == null ? null : leg.id,
                name: leg.name || null,
                sha: leg.head_sha || null,
                state: leg.status === 'completed' ?
                    (leg.conclusion || leg.status) : leg.status,
                at: leg.created_at || null,
                url: leg.html_url || null
            };
        }
        return out;
    }
